import { and, count, desc, eq, inArray, isNotNull, like, lt, ne, or, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { uniqueSlug } from "@/lib/slug";
import {
  archivePatch,
  restorePatch,
  shouldFilterArchived,
} from "@/lib/soft-delete";
import { getDb, issues, projectMembers, projects } from "@/server/db";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { toIsoTimestamp } from "@/types/common";
import { livePredicate, orgPredicate } from "./base-repository";
import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
import { toProject } from "./_mappers";
import type {
  CreateProjectInput,
  ListProjectsInput,
  UpdateProjectInput,
} from "@/schemas/project";
import type { ArchiveScope, OrgId, Page, ProjectId, UserId } from "@/types/common";
import type { Project, ProjectStats } from "@/types/project";
import type { SQL } from "drizzle-orm";

/**
 * Who a listing is read for. Passing none means an unrestricted read, which is
 * what background jobs want; passing one hides every private project the
 * viewer may not see, from the rows and the total alike.
 */
export interface ProjectViewer {
  readonly userId: UserId;
  /** Admins, owners and platform staff see every private project. */
  readonly seesAllPrivate: boolean;
}

/**
 * The `projects` rows `viewer` may see, or `undefined` when nothing is hidden.
 * A private project is visible to its lead and to its explicit members; the
 * service layer's `canViewProject()` states the same rule for single rows.
 */
export function visibleProjectPredicate(
  orgId: OrgId,
  viewer: ProjectViewer | undefined,
): SQL | undefined {
  if (viewer === undefined || viewer.seesAllPrivate) return undefined;

  return or(
    ne(projects.visibility, "private"),
    eq(projects.leadId, viewer.userId),
    inArray(
      projects.id,
      getDb()
        .select({ projectId: projectMembers.projectId })
        .from(projectMembers)
        .where(
