/**
 * Whether `actor` may see `project` at all. `org` and `public` projects are
 * visible to anyone the org already lets read projects. A `private` one is
 * visible only to admins and owners, platform staff, its lead and its explicit
 * members; to everyone else it must behave as if it did not exist.
 */
export async function canViewProject(
  actor: Actor,
  project: Project,
): Promise<boolean> {
  if (actor.orgId !== project.orgId) return false;
  if (project.visibility !== "private") return true;
  if (can(actor, "project:read_private", projectResource(project))) return true;

  return projectMemberRepo.isProjectMember(
    project.orgId,
    project.id,
    actor.userId,
  );
}

/**
 * `project` when the actor may see it, otherwise `null`. Callers hand the
 * result to `requireFound`, so a hidden project fails exactly like a missing one.
 */
export async function visibleProjectOrNull(
  actor: Actor,
  project: Project | null,
): Promise<Project | null> {
  if (project === null) return null;
  return (await canViewProject(actor, project)) ? project : null;
}

/**
 * An issue is visible exactly when its project is. Issue, attachment and
 * comment services use this to gate their reads and writes.
 */
export async function findVisibleIssue(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<Issue | null> {
  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (issue === null) return null;

  const project = await visibleProjectOrNull(
    actor,
    await projectRepo.findProjectById(orgId, issue.projectId),
  );
  return project === null ? null : issue;
}

/** What a listing needs to know about `actor` to leave hidden projects out. */
export function projectViewerFor(actor: Actor): projectRepo.ProjectViewer {
  return {
    userId: actor.userId,
    seesAllPrivate: can(actor, "project:read_private", orgResource(actor.orgId)),
  };
}

