import * as userRepo from "@/server/repositories/user-repository";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Comment } from "@/types/comment";
import type { Issue } from "@/types/issue";
import type { Actor } from "@/types/member";
import type { Project } from "@/types/project";

let cleanup: () => void;
let tenant: Tenant;
let outsider: Actor;
let secret: Project;
let secretIssue: Issue;
let openIssue: Issue;
let secretComment: Comment;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("visibility");

  const user = await userRepo.insertUser({
    email: "outsider@visibility.test",
    name: "visibility outsider",
    passwordHash: "seed",
  });
  await memberRepo.insertMember(tenant.org.id, user.id, "member", null);
  outsider = { userId: user.id, orgId: tenant.org.id, role: "member" };

  // Led by the `member` actor, so that actor is the only non-admin who sees it.
  secret = await projectRepo.insertProject({
    orgId: tenant.org.id,
    name: "Secret project",
    slug: "secret",
    key: "SEC",
    description: null,
    visibility: "private",
    leadId: tenant.userIds.member,
    color: "#6366f1",
    targetDate: null,
  });

  secretIssue = await issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, secret.id, { title: "Secret issue" }),
  );
  openIssue = await issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, tenant.project.id, { title: "Open issue" }),
  );
  secretComment = await commentService.createComment(tenant.actors.member, {
    orgId: tenant.org.id,
    issueId: secretIssue.id,
    body: "Only the lead can see this",
    parentId: null,
    mentionedUserIds: [],
  });
});

afterAll(() => {
  cleanup();
});

describe("services/project-service — private project visibility", () => {
  it("treats a private project as missing for an actor outside the rule", async () => {
    await expect(projectService.canViewProject(outsider, secret)).resolves.toBe(false);
    await expect(
      projectService.getProject(outsider, tenant.org.id, "secret"),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.getBoard(outsider, tenant.org.id, secret.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.getIssue(outsider, tenant.org.id, secretIssue.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      commentService.getThread(outsider, tenant.org.id, secretIssue.id),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("refuses every write to the project, its issues and comments as not found", async () => {
    const issueBefore = await issueRepo.findIssueById(tenant.org.id, secretIssue.id);
    const threadBefore = await commentRepo.listThread(tenant.org.id, secretIssue.id);
