    const staff: Actor = {
      userId: tenant.userIds.viewer,
      orgId: tenant.org.id,
      role: "viewer",
      isPlatformStaff: true,
    };

    await expect(projectService.canViewProject(staff, secret)).resolves.toBe(true);
  });

  it("shows the private project to an explicit member, and hides it again once removed", async () => {
    const viewer = tenant.actors.viewer;
    await expect(projectService.canViewProject(viewer, secret)).resolves.toBe(false);

    await projectMemberRepo.addProjectMember(tenant.org.id, secret.id, viewer.userId);
    await expect(
      projectService.getProject(viewer, tenant.org.id, "secret"),
    ).resolves.toMatchObject({ project: { id: secret.id } });

    const listed = await projectService.listProjects(viewer, {
      orgId: tenant.org.id,
      limit: 25,
      cursor: null,
    });
    expect(listed.items.map(({ project }) => project.id)).toContain(secret.id);

    await projectMemberRepo.removeProjectMember(tenant.org.id, secret.id, viewer.userId);
    await expect(
      projectService.getProject(viewer, tenant.org.id, "secret"),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("leaves org and public projects visible to anyone who can read projects", async () => {
    await expect(projectService.canViewProject(outsider, tenant.project)).resolves.toBe(true);
    await expect(
      projectService.getProject(outsider, tenant.org.id, "platform"),
    ).resolves.toMatchObject({ project: { id: tenant.project.id } });
  });

  it("moves access with the lead immediately when the lead changes", async () => {
    await expect(
      projectService.getProject(tenant.actors.member, tenant.org.id, "secret"),
    ).resolves.toMatchObject({ project: { id: secret.id } });

    await projectService.updateProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: secret.id,
      leadId: outsider.userId,
    });

    await expect(
      projectService.getProject(outsider, tenant.org.id, "secret"),
    ).resolves.toMatchObject({ project: { id: secret.id } });
    await expect(
      projectService.getProject(tenant.actors.member, tenant.org.id, "secret"),
    ).rejects.toBeInstanceOf(NotFoundError);
  });
});

