    await expect(projectService.canViewProject(outsider, secret)).resolves.toBe(false);
    await expect(
      projectService.getProject(outsider, tenant.org.id, "secret"),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.getBoard(outsider, tenant.org.id, secret.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.getIssue(outsider, tenant.org.id, secretIssue.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      commentService.getThread(outsider, tenant.org.id, secretIssue.id),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("refuses every write to the project, its issues and comments as not found", async () => {
    const issueBefore = await issueRepo.findIssueById(tenant.org.id, secretIssue.id);
    const threadBefore = await commentRepo.listThread(tenant.org.id, secretIssue.id);
    const projectBefore = await projectRepo.findProjectById(tenant.org.id, secret.id);

    await expect(
      issueService.createIssue(
        outsider,
        issueInput(tenant.org.id, secret.id, { title: "Sneaky issue" }),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.updateIssue(outsider, {
        orgId: tenant.org.id,
        issueId: secretIssue.id,
        title: "Hijacked title",
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.changeIssueStatus(outsider, {
        orgId: tenant.org.id,
        issueId: secretIssue.id,
        status: "done",
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.moveIssue(outsider, {
        orgId: tenant.org.id,
        issueId: secretIssue.id,
        toStatus: "done",
        toIndex: 0,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.assignIssue(outsider, {
        orgId: tenant.org.id,
        issueId: secretIssue.id,
        assigneeId: outsider.userId,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.archiveIssue(outsider, tenant.org.id, secretIssue.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      commentService.createComment(outsider, {
        orgId: tenant.org.id,
        issueId: secretIssue.id,
        body: "Hello from outside",
        parentId: null,
        mentionedUserIds: [],
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      commentService.updateComment(outsider, {
        orgId: tenant.org.id,
        commentId: secretComment.id,
        body: "Edited from outside",
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      commentService.deleteComment(outsider, {
        orgId: tenant.org.id,
        commentId: secretComment.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      projectService.updateProject(outsider, {
        orgId: tenant.org.id,
        projectId: secret.id,
        name: "Renamed",
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      projectService.archiveProject(outsider, {
        orgId: tenant.org.id,
        projectId: secret.id,
        archiveIssues: true,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      projectService.restoreProject(outsider, tenant.org.id, secret.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    expect(await issueRepo.findIssueById(tenant.org.id, secretIssue.id)).toEqual(issueBefore);
    expect(await commentRepo.listThread(tenant.org.id, secretIssue.id)).toEqual(threadBefore);
    expect(await projectRepo.findProjectById(tenant.org.id, secret.id)).toEqual(projectBefore);
    expect(
      await issueRepo.countIssues(tenant.org.id, secret.id, { includeArchived: true }),
    ).toBe(1);
  });

  it("leaves the private project and its issues out of listings and their totals", async () => {
    const projects = await projectService.listProjects(outsider, {
      orgId: tenant.org.id,
      limit: 25,
      cursor: null,
    });
    expect(projects.items.map(({ project }) => project.id)).toEqual([tenant.project.id]);
    expect(projects.total).toBe(1);

    const issues = await issueService.listIssues(outsider, {
      orgId: tenant.org.id,
      limit: 25,
      cursor: null,
    });
    expect(issues.items.map((issue) => issue.id)).toEqual([openIssue.id]);
    expect(issues.total).toBe(1);
  });

  it("shows the private project and its issues to admins and owners", async () => {
    for (const actor of [tenant.actors.admin, tenant.actors.owner]) {
      const projects = await projectService.listProjects(actor, {
        orgId: tenant.org.id,
        limit: 25,
        cursor: null,
      });
      expect(projects.total, actor.role).toBe(2);

      const issues = await issueService.listIssues(actor, {
        orgId: tenant.org.id,
        limit: 25,
        cursor: null,
      });
      expect(issues.total, actor.role).toBe(2);
    }

    await expect(
      projectService.getProject(tenant.actors.owner, tenant.org.id, "secret"),
    ).resolves.toMatchObject({ project: { id: secret.id } });
  });

  it("shows the private project to its lead", async () => {
    await expect(
      projectService.getProject(tenant.actors.member, tenant.org.id, "secret"),
    ).resolves.toMatchObject({ project: { id: secret.id } });
    await expect(
      issueService.getIssue(tenant.actors.member, tenant.org.id, secretIssue.id),
    ).resolves.toMatchObject({ issue: { id: secretIssue.id } });
  });

  it("shows the private project to platform staff", async () => {
    const staff: Actor = {
      userId: tenant.userIds.viewer,
      orgId: tenant.org.id,
      role: "viewer",
      isPlatformStaff: true,
    };

    await expect(projectService.canViewProject(staff, secret)).resolves.toBe(true);
  });

  it("shows the private project to an explicit member, and hides it again once removed", async () => {
    const viewer = tenant.actors.viewer;
    await expect(projectService.canViewProject(viewer, secret)).resolves.toBe(false);

    await projectMemberRepo.addProjectMember(tenant.org.id, secret.id, viewer.userId);
    await expect(
      projectService.getProject(viewer, tenant.org.id, "secret"),
    ).resolves.toMatchObject({ project: { id: secret.id } });

    const listed = await projectService.listProjects(viewer, {
      orgId: tenant.org.id,
      limit: 25,
      cursor: null,
    });
    expect(listed.items.map(({ project }) => project.id)).toContain(secret.id);

    await projectMemberRepo.removeProjectMember(tenant.org.id, secret.id, viewer.userId);
    await expect(
      projectService.getProject(viewer, tenant.org.id, "secret"),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("leaves org and public projects visible to anyone who can read projects", async () => {
    await expect(projectService.canViewProject(outsider, tenant.project)).resolves.toBe(true);
    await expect(
      projectService.getProject(outsider, tenant.org.id, "platform"),
    ).resolves.toMatchObject({ project: { id: tenant.project.id } });
  });

  it("moves access with the lead immediately when the lead changes", async () => {
    await expect(
      projectService.getProject(tenant.actors.member, tenant.org.id, "secret"),
    ).resolves.toMatchObject({ project: { id: secret.id } });

    await projectService.updateProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: secret.id,
      leadId: outsider.userId,
    });

    await expect(
      projectService.getProject(outsider, tenant.org.id, "secret"),
    ).resolves.toMatchObject({ project: { id: secret.id } });
    await expect(
      projectService.getProject(tenant.actors.member, tenant.org.id, "secret"),
    ).rejects.toBeInstanceOf(NotFoundError);
  });
});

